package com.johnny.hotel.cms;import com.johnny.hotel.cms.CmsModels.InternalScene;import com.johnny.hotel.common.Result;import lombok.RequiredArgsConstructor;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController@RequiredArgsConstructor@RequestMapping("/api/internal/site/scenes")@PreAuthorize("hasAnyRole('STAFF','FINANCE','MANAGER','OWNER','SUPER_ADMIN')")public class InternalSceneController{private final CmsService service;@GetMapping("/{id}")public Result<InternalScene>get(@PathVariable Long id){return Result.success(service.internalScene(id));}}
